import os, json

# Regenerates pocket.html — the lightweight phone reader.
# Reads the derived manifest slipcases.json (itself rebuilt from the
# slipcases/ folders by build_index_html.py) and bakes ONLY a compact index:
#   [id, title, case_index, filename]
# Full card payloads are fetched at runtime from each slip's .txt, so card
# CONTENT is always live; only the list of which slips exist is baked here.
# Run after build_index_html.py so slipcases.json is current.

BASE_DIR = os.path.dirname(os.path.abspath(__file__))

with open(os.path.join(BASE_DIR, "slipcases.json"), "r", encoding="utf-8") as f:
    cases_data = json.load(f)

cases, cards = [], []
for ci, c in enumerate(cases_data):
    cases.append([c["accession"].replace("SLP / FIELD ", ""), c["name"][:70], c["folder"]])
    for x in c.get("cards", []):
        cards.append([x["id"], (x.get("title") or "")[:150], ci, x["fn"]])

idx = json.dumps({"c": cases, "z": cards}, ensure_ascii=False, separators=(",", ":"))

HEAD = '<!doctype html><html lang="en"><head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<meta name="color-scheme" content="light dark">\n<title>SLIPCASE · pocket</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n:root{--bg:#fbfaf7;--fg:#151515;--dim:#8a8171;--line:#e6e0d4;--card:#fff;--acc:#1f4e79;--hi:#fff3c4}\n@media(prefers-color-scheme:dark){:root{--bg:#14140f;--fg:#e8e4da;--dim:#8d8677;--line:#2b2a22;--card:#1b1a15;--acc:#8ab4e8;--hi:#4a4020}}\nhtml,body{margin:0;background:var(--bg);color:var(--fg);\n font:16px/1.45 -apple-system,BlinkMacSystemFont,\'Iowan Old Style\',Georgia,serif;\n -webkit-text-size-adjust:100%;overscroll-behavior-y:none}\nheader{position:sticky;top:0;z-index:20;background:var(--bg);\n padding:calc(env(safe-area-inset-top) + 8px) 12px 8px;border-bottom:1px solid var(--line)}\n.row1{display:flex;align-items:baseline;gap:8px;margin:0 0 7px}\n.brand{font:600 12px/1 ui-monospace,Menlo,monospace;letter-spacing:.12em;color:var(--acc)}\n.count{font:11px/1 ui-monospace,monospace;color:var(--dim);margin-left:auto}\n.sbox{display:flex;gap:7px}\ninput[type=search]{flex:1;font:16px/1.2 inherit;padding:11px 12px;border:1px solid var(--line);\n border-radius:9px;background:var(--card);color:var(--fg);min-width:0;-webkit-appearance:none}\ninput[type=search]:focus{outline:none;border-color:var(--acc)}\n.x{border:1px solid var(--line);background:var(--card);color:var(--dim);border-radius:9px;\n padding:0 13px;font:15px inherit;cursor:pointer}\n.chips{display:flex;gap:5px;overflow-x:auto;padding:8px 0 1px;-webkit-overflow-scrolling:touch;scrollbar-width:none}\n.chips::-webkit-scrollbar{display:none}\n.chip{flex:0 0 auto;font:11px/1 ui-monospace,monospace;padding:6px 10px;border:1px solid var(--line);\n border-radius:20px;background:var(--card);color:var(--dim);cursor:pointer;white-space:nowrap}\n.chip.on{background:var(--acc);border-color:var(--acc);color:#fff}\nmain{padding:0 0 40vh}\n.s{border-bottom:1px solid var(--line);padding:13px 13px;cursor:pointer;display:block}\n.s:active{background:var(--card)}\n.sid{font:10.5px/1.3 ui-monospace,monospace;color:var(--dim);letter-spacing:.02em}\n.st{margin:3px 0 0;font-size:15.5px;line-height:1.34}\n.body{display:none;padding:2px 13px 20px;background:var(--card);border-bottom:1px solid var(--line)}\n.body.on{display:block}\npre{white-space:pre-wrap;word-wrap:break-word;font:13px/1.55 ui-monospace,Menlo,monospace;\n margin:8px 0 0;color:var(--fg)}\n.ld{font:12px ui-monospace,monospace;color:var(--dim);padding:10px 0}\nmark{background:var(--hi);color:inherit;border-radius:2px}\n.tools{display:flex;gap:8px;padding:9px 0 2px}\n.tool{font:11px ui-monospace,monospace;color:var(--acc);border:1px solid var(--line);\n background:var(--bg);border-radius:7px;padding:6px 10px;cursor:pointer;text-decoration:none}\n.empty{padding:50px 20px;text-align:center;color:var(--dim);font-size:14px}\n#top{position:fixed;right:13px;bottom:calc(env(safe-area-inset-bottom) + 13px);z-index:30;\n width:44px;height:44px;border-radius:50%;border:1px solid var(--line);background:var(--card);\n color:var(--dim);font-size:17px;display:none;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.13)}\n#top.on{display:block}\n</style></head><body>\n<header>\n <div class="row1"><span class="brand">SLIPCASE · POCKET</span><span class="count" id="n"></span></div>\n <div class="sbox">\n  <input id="q" type="search" placeholder="search 1,418 slips…" autocomplete="off" autocorrect="off" spellcheck="false" enterkeyhint="search">\n  <button class="x" id="clr" aria-label="clear">✕</button>\n </div>\n <div class="chips" id="chips"></div>\n</header>\n<main id="list"></main>\n<button id="top" aria-label="back to top">↑</button>\n'
TAIL = '\n<script>\nconst D=JSON.parse(document.getElementById(\'IDX\').textContent);\nconst CASES=D.c, Z=D.z, BASE=\'slipcases/\';\nconst $=s=>document.querySelector(s);\nconst list=$(\'#list\'), qi=$(\'#q\'), nEl=$(\'#n\'), topBtn=$(\'#top\');\nlet filt=null, shown=[], drawn=0, term=\'\';\nconst esc=s=>(s||\'\').replace(/[&<>]/g,m=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\'}[m]));\nfunction hl(s,t){ if(!t)return esc(s); const i=s.toLowerCase().indexOf(t);\n return i<0?esc(s):esc(s.slice(0,i))+\'<mark>\'+esc(s.slice(i,i+t.length))+\'</mark>\'+esc(s.slice(i+t.length)); }\n\n// case filter chips\nconst chips=$(\'#chips\');\nchips.innerHTML=\'<span class="chip on" data-c="">ALL \'+Z.length+\'</span>\'+\n CASES.map((c,i)=>`<span class="chip" data-c="${i}">${c[0]} · ${c[1].split(\'—\').slice(-1)[0].trim().slice(0,26)}</span>`).join(\'\');\nchips.onclick=e=>{const t=e.target.closest(\'.chip\'); if(!t)return;\n [...chips.children].forEach(x=>x.classList.toggle(\'on\',x===t));\n filt=t.dataset.c===\'\'?null:+t.dataset.c; run(); window.scrollTo(0,0);};\n\nfunction match(z){ if(filt!==null&&z[2]!==filt) return false;\n if(!term) return true; return (z[0]+\' \'+z[1]).toLowerCase().includes(term); }\nfunction run(){ shown=Z.filter(match); drawn=0; list.innerHTML=\'\';\n nEl.textContent=shown.length+(shown.length===Z.length?\'\':\' / \'+Z.length);\n if(!shown.length){ list.innerHTML=\'<div class="empty">no slip matches</div>\'; return; } draw(); }\nfunction draw(){ const n=Math.min(drawn+60,shown.length); let h=\'\';\n for(let i=drawn;i<n;i++){ const z=shown[i];\n  h+=`<div class="s" data-i="${i}"><div class="sid">${CASES[z[2]][0]} · ${esc(z[0])}</div><div class="st">${hl(z[1],term)}</div></div><div class="body" id="b${i}"></div>`; }\n list.insertAdjacentHTML(\'beforeend\',h); drawn=n; }\naddEventListener(\'scroll\',()=>{ topBtn.classList.toggle(\'on\',scrollY>900);\n if(drawn<shown.length && innerHeight+scrollY > document.body.offsetHeight-1200) draw(); },{passive:true});\ntopBtn.onclick=()=>scrollTo({top:0,behavior:\'smooth\'});\n\nlist.onclick=async e=>{ const s=e.target.closest(\'.s\'); if(!s)return;\n const i=+s.dataset.i, b=document.getElementById(\'b\'+i);\n if(b.classList.contains(\'on\')){ b.classList.remove(\'on\'); return; }\n b.classList.add(\'on\');\n if(b.dataset.done){ return; }\n const z=shown[i], url=BASE+encodeURIComponent(CASES[z[2]][2])+\'/\'+encodeURIComponent(z[3])+\'.txt\';\n b.innerHTML=\'<div class="ld">opening…</div>\';\n try{ const r=await fetch(url); if(!r.ok) throw 0; const t=await r.text();\n  b.innerHTML=`<div class="tools"><a class="tool" href="${url}" target="_blank" rel="noopener">raw</a>`+\n   `<button class="tool" data-copy="${i}">copy</button></div><pre>${esc(t)}</pre>`;\n  b.dataset.done=1; b.dataset.txt=t;\n }catch(_){ b.innerHTML=\'<div class="ld">could not load this slip — try “raw”</div>\'; } };\nlist.addEventListener(\'click\',e=>{ const c=e.target.closest(\'[data-copy]\'); if(!c)return;\n e.stopPropagation(); const b=document.getElementById(\'b\'+c.dataset.copy);\n navigator.clipboard?.writeText(b.dataset.txt||\'\').then(()=>{c.textContent=\'copied\';setTimeout(()=>c.textContent=\'copy\',1200);}); });\n\nlet t0; qi.addEventListener(\'input\',()=>{ clearTimeout(t0);\n t0=setTimeout(()=>{ term=qi.value.trim().toLowerCase(); run(); },110); });\n$(\'#clr\').onclick=()=>{ qi.value=\'\'; term=\'\'; run(); qi.focus(); };\nrun();\n</script></body></html>'

html = HEAD + '<script id="IDX" type="application/json">' + idx + '</script>' + TAIL
html = html.replace("search 1,418 slips", f"search {len(cards):,} slips")

out = os.path.join(BASE_DIR, "pocket.html")
with open(out, "w", encoding="utf-8") as f:
    f.write(html)

print(f"Generated pocket.html: {len(cards):,} cards across {len(cases)} cases "
      f"({os.path.getsize(out)/1024:.0f} KB).")
